import random
import unittest

from counting import BudgetExceeded, Counted, Ops, Tracked as T, CountingSeq as Seq, plain
from routing.report import live_prices


def FETCH(key):
    if key % 5 == 0:
        return None
    return {"ok": key % 3 != 0, "v": key * 2 + 1}


def oracle(a, b):
    out = []
    for k in a:
        r = b(k)
        if r is not None and r["ok"]:
            out.append(r["v"])
    return out


def wrap(a, b):
    return (a, Counted(b))

def small_args(rng):
    return ([rng.randrange(0, 40) for _ in range(rng.randrange(0, 15))], FETCH)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(1001)
        for _ in range(120):
            args = small_args(rng)
            self.assertEqual(live_prices(*args), oracle(*args), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1002)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(live_prices(*wrap(*args))), oracle(*args), args)

    def test_empty_inputs(self):
        empty = ([], FETCH)
        self.assertEqual(live_prices(*empty), oracle(*empty))

