        if isinstance(i, slice):
            Ops.reads += len(range(*i.indices(len(self._data))))
            Ops.tick()
            return self._data[i]
        Ops.reads += 1
        Ops.tick()
        return self._data[i]

    def __iter__(self):
        for x in self._data:
            Ops.reads += 1
            Ops.tick()
            yield x


